import assert from 'node:assert/strict';
import { readFile, writeFile, open } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import { setTimeout as pause } from 'node:timers/promises';
import { loadConfig } from '../../../services/pi-orchestrator/src/config.ts';
import { SqliteOrchestratorState } from '../../../services/pi-orchestrator/src/sqlite-store.ts';
import { OrchestratorApplication } from '../../../services/pi-orchestrator/src/application.ts';
import { PiBenchmarkRuntime } from '../../../services/pi-orchestrator/src/benchmark-runtime.ts';

const root = process.cwd();
const dir = resolve('.forge/benchmarks/schema-descriptions-run-20260908');
const preparation = resolve('.forge/benchmarks/schema-descriptions-ready-20260908');
const card = JSON.parse(await readFile('docs/archive/benchmarks/benchmark-luna-schema-descriptions-ready-2026-09-08.json', 'utf8')).experiment_card;
const schedule = ['A1', 'B1', 'B2', 'A2'];
const receipts: any[] = [];
const captures: Promise<void>[] = [];
const runs: any[] = [];
const nativeFetch = globalThis.fetch;
let dispatched = 0;
let currentLabel = 'none';
let captureFailure: string | null = null;
const save = (name: string, value: unknown) => writeFile(join(dir, name), JSON.stringify(value, null, 2), { flag: 'wx' });
await save('execution-start.json', { task: 'Forge-20260908-02', at: new Date().toISOString(), max_requests: 64, cny_cap_revoked: true, cny_cost: null, subscription_oauth: true, schedule, card_sha256: card.card_sha256 });

globalThis.fetch = async (input: any, init?: any) => {
  const url = new URL(typeof input === 'string' || input instanceof URL ? input : input.url);
  const isGeneration = url.hostname === 'chatgpt.com' && /\/responses$/.test(url.pathname);
  if (!isGeneration) return nativeFetch(input, init);
  assert.ok(dispatched < 64, 'Authorized 64-request ceiling reached');
  const index = ++dispatched;
  const receipt: any = { index, label: currentLabel, started_at: new Date().toISOString(), host: url.hostname, path: url.pathname };
  receipts.push(receipt);
  await save(`request-${String(index).padStart(2, '0')}-admitted.json`, receipt);
  try {
    const response = await nativeFetch(input, init);
    receipt.http_status = response.status;
    const clone = response.clone();
    captures.push((async () => {
      const file = await open(join(dir, `response-${String(index).padStart(2, '0')}.sse`), 'wx');
      try {
        if (clone.body) {
          const reader = clone.body.getReader();
          for (;;) {
            const item = await reader.read();
            if (item.done) break;
            await file.write(item.value);
          }
        }
        receipt.capture_complete = true;
      } catch (error) {
        receipt.capture_error = error instanceof Error ? error.message : String(error);
        captureFailure = receipt.capture_error;
      } finally {
        await file.close();
        receipt.ended_at = new Date().toISOString();
        await save(`request-${String(index).padStart(2, '0')}-receipt.json`, receipt);
      }
    })());
    return response;
  } catch (error) {
    receipt.transport_error = error instanceof Error ? error.message : String(error);
    receipt.ended_at = new Date().toISOString();
    await save(`request-${String(index).padStart(2, '0')}-receipt.json`, receipt);
    throw error;
  }
};

const config = loadConfig({
  PI_ORCHESTRATOR_AGENT_DIR: '<local-home>/.pi/agent',
  PI_ORCHESTRATOR_STATE_DB: join(dir, 'orchestrator.sqlite3'),
  SHISUI_DATA_SKILLS_DIR: root,
  PI_BENCHMARK_CONCURRENCY: '2',
  FORGE_BASE_URL: 'http://127.0.0.1:19043',
  FORGE_PI_SERVICE_KEY: 'req065-loopback-only',
});
const state = new SqliteOrchestratorState(config.stateDbPath);
const application = new OrchestratorApplication({ config, state });
const runtime = new PiBenchmarkRuntime(config, application);
let failure: string | null = null;
try {
  for (const label of schedule) {
    currentLabel = label;
    const frozen = JSON.parse(await readFile(join(preparation, label.startsWith('A') ? 'control.frozen.json' : 'treatment.frozen.json'), 'utf8'));
    const started = await runtime.start({ provider: 'openai-codex', model: 'gpt-5.6-luna', caseIds: card.case_ids, confirmModelCalls: 16, protocolManifest: frozen.manifest });
    assert.equal(started.model.revision, card.model.expected_revision);
    await save(`${label}-started.json`, started);
    console.log(JSON.stringify({ label, run_id: started.run_id, status: started.status }));
    let run: any;
    let prior = '';
    for (;;) {
      run = runtime.get(started.run_id);
      const progress = JSON.stringify({ label, run_id: run.run_id, status: run.status, dispatched_calls: run.dispatched_calls, completed_calls: run.completed_calls, actual_http_requests: dispatched });
      if (progress !== prior) { console.log(progress); prior = progress; }
      if (['completed', 'failed', 'stopped', 'interrupted'].includes(run.status)) break;
      await pause(1000);
    }
    await Promise.all(captures);
    await save(`${label}-run.json`, run);
    await save(`${label}-logs.json`, runtime.logs(started.run_id));
    runs.push({ label, run_id: run.run_id, status: run.status, dispatched_calls: run.dispatched_calls, completed_calls: run.completed_calls });
    if (run.status !== 'completed' || run.dispatched_calls !== 16 || captureFailure || run.cases.some((c: any) => ['forge', 'direct'].some(a => c[a]?.usage_observed !== true))) {
      failure = `Stop after ${label}: terminal=${run.status}, capture=${captureFailure}, incomplete generation/usage possible`;
      break;
    }
  }
} catch (error) {
  failure = error instanceof Error ? error.message : String(error);
  console.error(failure);
} finally {
  await runtime.close();
  await Promise.all(captures);
  state.close();
  globalThis.fetch = nativeFetch;
  const result = { task: 'Forge-20260908-02', at: new Date().toISOString(), status: failure ? 'stopped_fail_closed' : 'completed', failure, actual_http_requests: dispatched, receipts, runs, planned_calls: 64, cny_cost: null, cny_cost_note: 'Not computable from subscription OAuth; no free-use guarantee', no_retries_or_replacements: true };
  await save('execution-result.json', result);
  console.log(JSON.stringify(result));
}

