import os, sys, types, json, hashlib, math
from pathlib import Path
from datetime import datetime, timezone
from collections import Counter
os.environ['FORGE_DISABLE_DOTENV'] = 'true'
sys.path.insert(0, str(Path.cwd()))
cfg_module = types.ModuleType('config')
cfg_module.cfg = types.SimpleNamespace(PI_SERVICE_API_KEYS=['req065-loopback-only'])
sys.modules['config'] = cfg_module
from forge import bird_benchmark as bird

root = Path('.forge/benchmarks/schema-descriptions-run-20260908')
ready = json.loads(Path('docs/archive/benchmarks/benchmark-luna-schema-descriptions-ready-2026-09-08.json').read_text())
execution = json.loads((root/'execution-result.json').read_text())
def save(name, value):
    with (root/name).open('x') as out: json.dump(value, out, ensure_ascii=False, indent=2)
def key(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
def raw_key(arm, raw):
    if arm == 'forge': return key(raw['tool_arguments'])
    return ''.join(b.get('text', '') for m in raw['assistant'] for b in m['content'] if b['type']=='text')

runs, replays, indexes, response_checks = {}, {}, {}, []
for item in execution['runs']:
    label = item['label']
    run = json.loads((root/f'{label}-run.json').read_text())
    runs[label] = run
    replay = bird.replay(run)
    replays[label] = replay
    save(f'{label}-replay.json', replay)
    indexes[label] = {(r['case_id'],r['arm']):r for r in replay['candidates']}
    original = {(c['case_id'],a):c[a] for c in run['cases'] for a in ('forge','direct')}
    fields = ('scored','compile_status','execution_status','official_ea','contract_accuracy','sql')
    for ident, r in indexes[label].items():
        different = [f for f in fields if r['evaluation'].get(f)!=original[ident].get(f)]
        response_checks.append({'label':label,'case_id':ident[0],'arm':ident[1],'replay_differences':different})
    # Link captured original SSE to the Pi raw candidate without printing private reasoning.
    available = [(cid,arm,metric) for (cid,arm),metric in original.items() if metric.get('raw_output') and metric.get('output') is not None]
    for receipt in [r for r in execution['receipts'] if r['label']==label]:
        p = root/f"response-{receipt['index']:02d}.sse"
        events = [json.loads(line[6:]) for line in p.read_text().splitlines() if line.startswith('data: ') and line[6:]!='[DONE]']
        done = [e['item'] for e in events if e.get('type')=='response.output_item.done']
        calls = [i for i in done if i['type']=='function_call']
        if calls:
            arm='forge'; raw=key(json.loads(calls[0]['arguments']))
        else:
            arm='direct'; raw=''.join(b.get('text','') for i in done if i['type']=='message' for b in i.get('content',[]) if b.get('type')=='output_text')
        matched = [(cid,a,m) for cid,a,m in available if a==arm and raw_key(a,m['raw_output'])==raw]
        finals = [e['response'] for e in events if e.get('type')=='response.completed']
        check = {'label':label,'request_index':receipt['index'],'http_status':receipt.get('http_status'),'sse_sha256':'sha256:'+hashlib.sha256(p.read_bytes()).hexdigest(),'raw_candidate_matched':bool(matched),'provider_completed':bool(finals)}
        if matched:
            cid,a,m=matched[0]; available.remove(matched[0]); check.update(case_id=cid,arm=a)
            if finals:
                usage=finals[-1].get('usage',{})
                check['total_tokens_match']=usage.get('total_tokens')==m['total_tokens']
                check['completion_tokens_match']=usage.get('output_tokens')==m['completion_tokens']
        response_checks.append(check)
    if available:
        response_checks.append({'label':label,'unmatched_pi_candidates':[(c,a) for c,a,_ in available]})
save('original-response-and-replay-checks.json',response_checks)

comparisons = {}
for repeat in (1,2):
    a,b=f'A{repeat}',f'B{repeat}'
    if a in replays and b in replays:
        comparisons[str(repeat)] = bird.compare(replays[a],replays[b])
save('paired-comparisons.json',comparisons)

def summary(labels, arm):
    metrics=[c[arm] for label in labels if label in runs for c in runs[label]['cases']]
    scores=[indexes[label][c['case_id'],arm]['evaluation'] for label in labels if label in indexes for c in runs[label]['cases']]
    times=sorted(m['generation_ms'] for m in metrics if isinstance(m.get('generation_ms'),(int,float)))
    result={k:{'correct':sum(e.get(k) is True for e in scores),'failed':sum(e.get(k) is False for e in scores),'unknown':sum(e.get(k) is None for e in scores),'observed_denominator':len(scores)} for k in ('official_ea','contract_accuracy')}
    result.update(total_tokens=sum(m['total_tokens'] for m in metrics if m.get('usage_observed')),unknown_usage=sum(m.get('usage_observed') is not True for m in metrics),generation_p95_ms=times[math.ceil(.95*len(times))-1] if times else None,execution_passed=sum(e.get('execution_status')=='passed' for e in scores))
    correct=result['official_ea']['correct']
    result['tokens_per_ex_correct']=result['total_tokens']/correct if correct else None
    return result
summaries={l:{a:summary([l],a) for a in ('forge','direct')} for l in runs}
combined={c:{a:summary([c+'1',c+'2'],a) for a in ('forge','direct')} for c in ('A','B')}
complete=execution['actual_http_requests']==64 and set(runs)=={'A1','B1','B2','A2'} and all(r['status']=='completed' for r in runs.values()) and all(r['complete'] for r in replays.values()) and all(s['unknown_usage']==0 for s in summaries.values() for s in s.values())
fg=combined['B']['forge']['official_ea']['correct']-combined['A']['forge']['official_ea']['correct']
dg=combined['B']['direct']['official_ea']['correct']-combined['A']['direct']['official_ea']['correct']
transitions=[]
for rep in (1,2):
    a,b=f'A{rep}',f'B{rep}'
    if a in indexes and b in indexes:
        for cid in ready['experiment_card']['case_ids']:
            for arm in ('forge','direct'):
                ae,be=indexes[a][cid,arm]['evaluation'],indexes[b][cid,arm]['evaluation']
                transitions.append({'repeat':rep,'case_id':cid,'arm':arm,'ex_A':ae['official_ea'],'ex_B':be['official_ea'],'contract_A':ae['contract_accuracy'],'contract_B':be['contract_accuracy']})
stable=[t['case_id'] for t in ready['experiment_card']['targets'] if sum(x['case_id']==t['case_id'] and x['arm']=='forge' and x['ex_A'] is False and x['ex_B'] is True and x['contract_B'] is True for x in transitions)==2]
regressions=[t for t in transitions if t['arm']=='forge' and ((t['ex_A'] is True and t['ex_B'] is not True) or (t['contract_A'] is True and t['contract_B'] is not True))]
controls={t['case_id'] for t in ready['experiment_card']['controls']}
control_correct=sum(t['arm']=='forge' and t['case_id'] in controls and t['ex_B'] is True for t in transitions)
def ratio(b,a): return b/a if a and b is not None else None
token_ratio=ratio(sum(v['total_tokens'] for v in combined['B'].values()),sum(v['total_tokens'] for v in combined['A'].values()))
per_correct_ratio=ratio(combined['B']['forge']['tokens_per_ex_correct'],combined['A']['forge']['tokens_per_ex_correct'])
p95_ratio=ratio(combined['B']['forge']['generation_p95_ms'],combined['A']['forge']['generation_p95_ms'])
originals_ok=all(not c.get('replay_differences') and not c.get('unmatched_pi_candidates') and ('request_index' not in c or all(c.get(k) is True for k in ('raw_candidate_matched','provider_completed','total_tokens_match','completion_tokens_match'))) for c in response_checks)
gates={'complete_64_scored_known_usage':complete,'original_response_and_replay_consistent':originals_ok,'both_repeats_comparable':len(comparisons)==2 and all(v.get('comparable') for v in comparisons.values()),'forge_gain_at_least_2':complete and fg>=2,'repeat_stable_target_gain':complete and bool(stable),'zero_forge_ex_contract_regressions':complete and not regressions,'control_B_ex_8_of_8':complete and control_correct==8,'forge_gain_minus_absolute_direct_gain_at_least_2':complete and fg-abs(dg)>=2,'total_tokens_ratio_at_most_1_2':complete and token_ratio is not None and token_ratio<=1.2,'forge_tokens_per_correct_not_increased':complete and per_correct_ratio is not None and per_correct_ratio<=1,'forge_generation_p95_ratio_at_most_1_25':complete and p95_ratio is not None and p95_ratio<=1.25}
report={'schema_version':'benchmark-luna-schema-descriptions-result-v1','task_id':'Forge-20260908-02','requirement':'REQ-2026-09-08-065','at':datetime.now(timezone.utc).isoformat(),'execution':execution,'summaries':summaries,'combined':combined,'paired_transitions':transitions,'stable_target_gains':stable,'forge_regressions':regressions,'control_B_ex_correct':control_correct,'delta_forge':fg,'delta_direct':dg,'total_tokens_ratio':token_ratio,'forge_tokens_per_correct_ratio':per_correct_ratio,'forge_generation_p95_ratio':p95_ratio,'gates':gates,'all_gates_passed':all(gates.values()),'decision':'Keep default off. Mechanism-screening only; no broad accuracy superiority or automatic rollout.','cny_cost':None,'cny_cap_revoked':True,'historical_scores_unchanged':True,'new_model_calls_during_analysis':0,'evidence_root':str(root)}
save('result.json',report)
print(json.dumps({k:report[k] for k in ['combined','delta_forge','delta_direct','stable_target_gains','forge_regressions','control_B_ex_correct','total_tokens_ratio','forge_tokens_per_correct_ratio','forge_generation_p95_ratio','gates','all_gates_passed']},ensure_ascii=False,indent=2))
